        "code": "using UnityEngine;\n\npublic class EfeitoMagiaDemo : MonoBehaviour\n{\n    void Start()\n    {\n        Debug.Log(\"Efeito de Partículas de Magia Dimensional ativado com burst de 30 fagulhas.\");\n    }\n}",
